
use super::*;
fn outcome(request:Request)->(&'static str,String){match request{Request::List(path)=>("List",path),Request::Load(path)=>("Load",path),Request::Recovery(path)=>("Recovery",path),Request::RecoveryList(path)=>("RecoveryList",path),Request::HistoryPage(_)=>("HistoryPage",String::new()),Request::CreateFile(path)=>("CreateFile",path),Request::CreateDirectory(path)=>("CreateDirectory",path),Request::Rename{destination,..}=>("Rename",destination),Request::Retain{path,..}=>("Retain",path),_=>panic!("closed browser fixture request")}}
#[test]
fn browser_replays_neutral_navigation_confirmations_and_observed_requests(){
 let fixture:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();
 for row in fixture["navigation"].as_array().unwrap(){let mut state=BrowserState{directory:row["directory"].as_str().unwrap().into(),query:row["query"].as_str().unwrap().into(),history:row["history"].as_bool().unwrap(),history_root:row["root"].as_str().map(str::to_owned),..Default::default()};if let Some(path)=row["entry"]["path"].as_str(){state.entries.push(Entry{path:path.into(),name:"entry".into(),directory:row["entry"]["directory"].as_bool().unwrap()});state.visible.push(0);}let request=if row["action"]=="parent"{state.browse_parent()}else{state.activate(0).unwrap()};assert_eq!(outcome(request),(row["expectedKind"].as_str().unwrap(),row["expectedPath"].as_str().unwrap().into()),"{}",row["id"]);}
 let root=std::path::PathBuf::from(std::env::var_os("SEMIO_TEST_ARTIFACT_DIR").expect("owned browser artifacts required")).join(format!("browser{}",std::process::id()));std::fs::create_dir_all(&root).unwrap();std::fs::write(root.join("old"),"kept").unwrap();let workspace=crate::Workspace::new(&root).unwrap();workspace.create_file("seed","",&std::sync::atomic::AtomicBool::new(false),&mut |_|{}).unwrap();let revision=workspace.inspect_entry("old",&std::sync::atomic::AtomicBool::new(false),&mut |_|{}).unwrap();
 for row in fixture["forms"].as_array().unwrap(){let kind=match row["action"].as_str().unwrap(){"create-file"=>EntryAction::CreateFile,"create-directory"=>EntryAction::CreateDirectory,"rename"=>EntryAction::Rename,"retain"=>EntryAction::Retain,_=>panic!("closed entry action")};let state=BrowserState{directory:row["directory"].as_str().unwrap().into(),history:row["history"].as_bool().unwrap(),form:Some(EntryForm{kind,path:row["path"].as_str().unwrap().into(),revision:row["observed"].as_bool().unwrap().then_some(revision.clone()),busy:row["busy"].as_bool().unwrap()}),..Default::default()};let actual=state.prepare_entry(row["value"].as_str().unwrap()).map(outcome).unwrap_or_else(|error|(error.id(),String::new()));assert_eq!(actual,(row["expectedKind"].as_str().unwrap(),row["expectedPath"].as_str().unwrap().into()),"{}",row["id"]);}
 for row in fixture["history"].as_array().unwrap(){let result=history_confirmation(row["active"].as_str().unwrap(),row["pending"].as_str(),if row["action"]=="archive"{HistoryAction::Archive}else{HistoryAction::Reconcile},row["value"].as_str().unwrap(),row["busy"].as_bool().unwrap());assert_eq!(result.map(|_|"Confirmed").unwrap_or_else(BrowserError::id),row["expected"].as_str().unwrap());}
 let inspection=workspace.inspect_history(&std::sync::atomic::AtomicBool::new(false),&mut |_|{}).unwrap();let mut state=BrowserState::default();state.history_form=Some(HistoryForm{action:HistoryAction::Reconcile,expected:inspection.clone(),busy:false});assert!(!inspection.active.is_empty());assert!(matches!(state.prepare_history(&inspection.active),Ok(Request::ReconcileHistory(_))));assert!(matches!(state.next_page(),Err(BrowserError::NoPage)));state.history_form=None;state.entries=vec![Entry{path:"folder".into(),name:"folder".into(),directory:true},Entry{path:"a.txt".into(),name:"a.txt".into(),directory:false}];assert_eq!(state.rows(),vec!["folder/","a.txt"]);state.directory="src".into();assert_eq!(state.rows(),vec!["../","folder/","a.txt"]);state.query="A".into();assert_eq!(state.rows(),vec!["a.txt"]);assert_eq!(state.visible,vec![1]);drop(workspace);std::fs::remove_dir_all(root).unwrap();
}
